@startuml

class Bettor {
  + name : string
  + id : int
}

class Race {
  + raceId : string
  + startTime : datetime
}

class Runner {
  + runnerId : string
}

class Horse {
  + name : string
  + age : int
}

class Jockey {
  + name : string
  + licenseNumber : string
}

class Bet {
  + amount : double
  + odds : double
}

class Winner {
  + isWinner : boolean
}

Horse "1" *-- "1" Runner
Jockey "1" -- "1" Runner

Race "1" *-- "1..*" Runner
Runner "1" -- "0..*" Bet : participated_in
Bet "1..*" -- "1" Race : refers_to
Bettor "1" -- "0..*" Bet : places
Bettor "1" -- "0..*" Bet : owner_of

@enduml

